import os,json,shutil,hashlib,datetime,urllib.request
root=r'E:\WebAIBridge\app\data'
base='http://127.0.0.1:17448'
out={'at':datetime.datetime.now().isoformat(timespec='seconds'),'operation':'freeze_bridge_autonomy_no_agent_send','backup':{},'steps':[]}
def api(path,method='GET',body=None,timeout=6):
 data=None if body is None else json.dumps(body).encode('utf-8')
 req=urllib.request.Request(base+path,data=data,headers={'Content-Type':'application/json'} if data else {},method=method)
 with urllib.request.urlopen(req,timeout=timeout) as r:return json.load(r)
before=api('/api/operator-lifecycle')
cfg=api('/api/supervisor-watchdog?detect=0').get('config',{})
out['previous']={'lifecycle':before.get('mode'),'queuePaused':before.get('queuePaused'),'supervisorEnabled':cfg.get('enabled'),'allowAutonomousSend':cfg.get('allowAutonomousSend'),'autoContinueEnabled':cfg.get('autoContinueEnabled')}
if not os.path.isdir(root):raise RuntimeError('expected bridge data directory missing')
stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ')
dest=os.path.join(root,'backups','owner-r45-safety-'+stamp)
os.makedirs(dest,exist_ok=False)
files=['state.json','supervisor-watchdog.json','supervisor-watchdog-state.json','managed-chat-status.json','managed-project-status.json','managed-project-timeline.json','projects-live-control-plane-r41.json','projects-operation-ledger-r41.json']
copies=[]
for name in files:
 src=os.path.join(root,name)
 if not os.path.isfile(src):continue
 dst=os.path.join(dest,name)
 shutil.copy2(src,dst)
 with open(src,'rb') as f:h=hashlib.file_digest(f,'sha256').hexdigest()
 with open(dst,'rb') as f:hcopy=hashlib.file_digest(f,'sha256').hexdigest()
 if h!=hcopy:raise RuntimeError('backup integrity mismatch:'+name)
 copies.append({'name':name,'sha256':h,'size':os.path.getsize(src)})
out['backup']={'directory':dest,'files':len(copies),'verified':len(copies)>0}
manifest={'object':'bridge.r45.owner_safety_snapshot.v1','createdAt':stamp,'backupDir':dest,'files':copies,'original':out['previous'],'restoreRequiresExplicitUserAction':True}
with open(os.path.join(dest,'manifest.json'),'w',encoding='utf-8') as f:json.dump(manifest,f,indent=2)
try:
 a=api('/api/pause','POST',{'paused':True},timeout=8)
 out['steps'].append({'name':'queue_pause','http_success':True,'paused':a.get('paused')})
except Exception as e:
 out['steps'].append({'name':'queue_pause','error':type(e).__name__})
try:
 a=api('/api/supervisor-watchdog','PUT',{'enabled':False,'allowAutonomousSend':False,'autoContinueEnabled':False,'sendProtectedDraftEnabled':False,'migrationEnabled':False,'openExistingChatIfMissing':False,'allowProfileRecovery':False,'stopStaleGenerationEnabled':False},timeout=12)
 out['steps'].append({'name':'disable_watchdog_and_sends','http_success':True,'enabled':a.get('config',{}).get('enabled')})
except Exception as e:
 out['steps'].append({'name':'disable_watchdog_and_sends','error':type(e).__name__})
try:
 b=api('/api/operator-lifecycle',timeout=4)
 c=api('/api/supervisor-watchdog?detect=0',timeout=4).get('config',{})
 out['verified']={'queuePaused':b.get('queuePaused'),'watchdogEnabled':c.get('enabled'),'allowAutonomousSend':c.get('allowAutonomousSend'),'autoContinueEnabled':c.get('autoContinueEnabled')}
 out['fullyFrozen']=b.get('queuePaused') is True and c.get('enabled') is False and c.get('allowAutonomousSend') is False and c.get('autoContinueEnabled') is False
except Exception as e:out['readback_error']=type(e).__name__
print(json.dumps(out,ensure_ascii=True)[:4800])
